# rev5 (EXP-687, curmudgeon cycle-4 C4-2). NOT PRE-REGISTERED. Lag-aware version of the REV4-JOINT control-calibrated amplitude test.
# For every control day (rev4 null set: all 8 stations evaluable, max Kp(12-24 UT)<=3), inject at each station a response
# kappa x (-10.9 x coverage_s x FSF_s) x lag(obscuration_s, L)/peak (first-order relaxation, true lag L = 0/15/30/60 min) into the REAL
# deviation, refit A_s with the rev4 template (tau 0 or 30, linear or quadratic trend), form the rev4 residual with the UNINJECTED null
# mean/sd, and WLS-fit k x FSF exactly as rev4_profile.py. Expected recovered k for a true response (kappa, L) = mean over control days.
# Distance of the event k from it is expressed in rev4's units (control-day SD of uninjected k). kappa = 1 (-10.9 baseline) and 1.672.
import sys,json,hashlib; sys.path.insert(0,'/tmp/ecl2'); sys.path.insert(0,'/tmp/ecl3'); sys.path.insert(0,'/tmp/ecl4')
import numpy as np
from lib import *
from tests import lag
from rev3_fits import jfit
from rev4_profile import FR,ST,BOU,profiles,wls
LAGS=[0,15,30,60]; KAPPAS=[1.0,1.672]
def fits(comp,tau,quad,inj=None):
    A={}
    for s in ST:
        d=load(s); ob=obsc_series(s); tp=lag(ob,tau); tp=tp/tp.max()
        c1,tm,c4=contacts(s); w=np.arange(c1-60,c4+61); A[s]={}
        tr=None
        if inj: L,amp=inj[0],inj[1][s]; tr=lag(ob,L); tr=tr/tr.max()
        for day in sorted(d):
            b,_=base(d,comp,Q,exclude=day); x=d[day][comp]-b
            if tr is not None and day!=EVD: x=x+amp*tr
            a=jfit(x,w,tp,quad)
            if np.isfinite(a): A[s][day]=a
    return A
def ks(A0,A1,covin,P):
    days=sorted(set.intersection(*[set(A0[s]) for s in ST]))
    ok=[dd for dd in days if dd==EVD or max(KPD[dd][4:8])<=3.0]; out={}
    for day in ok:
        R_={};S_={}
        for s in ST:
            nul=np.array([A0[s][x] for x in ok if x not in (day,EVD)]); mu,sd=nul.mean(),nul.std(ddof=1)
            cov=FR[s]['cov'] if covin=='dome_coverage' else O[s]['max_obsc']; den=BOU*cov
            R_[s]=(A1[s][day]-mu)/den; S_[s]=sd/abs(den)
        out[day]=wls(R_,S_,P,ST)[0]
    return out
R={'_meta':dict(script='rev5_lag_joint.py',preregistered=False,component='Z',
   admissible_lag_window='dome texts: paragraph \"Z minimum within 30 minutes of maximum eclipse coverage\" (03-predictions.txt:72-73), Tier 1 \"umbra-locked\" (:107), card \"during totality\" (:1425-1426) -> true lag <= 30 min admissible; 60 min reported outside the window',
   distance='(expected recovered k - event k) / control-day SD of uninjected k (rev4 units)')}
P,_=profiles('Z'); FSF=P['dome_FSF']
for tau in (0,30):
    for quad in (False,True):
        A0=fits('Z',tau,quad)
        for covin in ('dome_coverage','ephemeris_obscuration'):
            k0=ks(A0,A0,covin,FSF); kev=k0[EVD]; kc=np.array([v for d_,v in k0.items() if d_!=EVD]); sdc=float(kc.std(ddof=1))
            rec=dict(event_k=round(kev,3),control_k_mean=round(float(kc.mean()),3),control_k_sd=round(sdc,3),rows={})
            for kap in KAPPAS:
                amps={s:kap*BOU*(FR[s]['cov'] if covin=='dome_coverage' else O[s]['max_obsc'])*FR[s]['fsf'] for s in ST}
                for L in LAGS:
                    A1=fits('Z',tau,quad,inj=(L,amps)); k1=ks(A0,A1,covin,FSF)
                    ki=np.array([v for d_,v in k1.items() if d_!=EVD]); ek=float(ki.mean())
                    rec['rows'][f'kappa{kap}|true_lag{L}']=dict(expected_k=round(ek,3),recovery=round(ek/kap,3),injected_k_sd=round(float(ki.std(ddof=1)),3),
                        distance_ctlsd=round((ek-kev)/sdc,2),n_ge_event=int(np.sum(ki<=kev)),admissible=bool(L<=30))
            key=f"Z|obsc_tau{tau}|{'quad' if quad else 'lin'}|{covin}"
            R[key]=rec
            print(key,'k_ev',round(kev,3),'sd',round(sdc,3),' '.join(f"{k}:{v['expected_k']}/{v['distance_ctlsd']}" for k,v in rec['rows'].items()),flush=True)
summ={}
for kap in KAPPAS:
    for scope,lags in [('admissible_lag_le_30',[0,15,30]),('all_lags_0_60',LAGS)]:
        ds=[R[k]['rows'][f'kappa{kap}|true_lag{L}']['distance_ctlsd'] for k in R if k.startswith('Z|') for L in lags]
        summ[f'kappa{kap}|{scope}|any_template']=dict(min=min(ds),max=max(ds))
        # lag-matched: template tau equals the nearest true lag (tau0 for L 0/15, tau30 for L 30/60)
        dm=[R[k]['rows'][f'kappa{kap}|true_lag{L}']['distance_ctlsd'] for k in R if k.startswith('Z|') for L in lags if (('tau0|' in k) == (L<=15))]
        summ[f'kappa{kap}|{scope}|lag_matched_template']=dict(min=min(dm),max=max(dm))
R['summary']=summ
json.dump(R,open('/tmp/ecl5/rev5_lag_joint.json','w'),indent=1)
for k,v in summ.items(): print(k,v)
print('sha256',hashlib.sha256(open('/tmp/ecl5/rev5_lag_joint.json','rb').read()).hexdigest())
